contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount + 1, "insufficient balance");

        // Fund the test contract with enough Ether to deposit amount + 1 wei.
        // The caller must already have enough balance; amount comes from parameter.

        // Record the contract's balance before deposit.
        uint256 balanceBefore = address(c).balance;

        // Deposit the test amount.
        c.deposit{value: amount}();

        // Observe the sender's credit by depositing 1 wei more: credit should be amount + 1.
        c.deposit{value: 1}();

        uint256 balanceAfterDeposits = address(c).balance;

        // Attempt the withdrawal.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfterWithdraw = address(c).balance;

        // General rule: if the withdrawal succeeded, the contract balance must have decreased
        // by exactly the total deposited (amount + 1); otherwise it must be unchanged.
        assert(
            (reverted && balanceAfterWithdraw == balanceAfterDeposits) ||
            (!reverted && balanceAfterWithdraw + amount + 1 == balanceAfterDeposits)
        );
    }

    receive() external payable {}
}

